def two_sum(nums, target):
    seen = {}
    for i, n in enumerate(nums):
        if target - n in seen:
            return [seen[target - n], i]
        seen[n] = i
    return []


def longest_unique(s):
    best = 0
    for i in range(len(s)):
        chars = set()
        for j in range(i, len(s)):
            if s[j] in chars:
                break
            chars.add(s[j])
            best = max(best, j - i + 1)
    return best
